'use strict';
const galleryGroups={
 'people-light-v1.png':['Con người','Tiên rừng','Người lùn'],
 'people-dark-v1.png':['Orc','Goblin','Tộc Thú'],
 'wildlife-animation-v1.png':['Cừu','Sói','Hươu','Thỏ','Cáo'],
 'dinosaurs-animation-v1.png':['Stegosaurus','Allosaurus','Triceratops','Velociraptor'],
 'ice-animation-v1.png':['Ma mút','Thú răng kiếm']
};
let galleryAction=1,galleryLoaded=0;const galleryCards=[];let gallerySpeed=1,galleryClock=0,lastGalleryTime=null;
for(const [frame,name] of [[0,'Đứng'],[1,'Đi'],[3,'Làm việc / Kiếm ăn'],[4,'Mang gỗ / Cảnh giác'],[5,'Ngủ']]){const b=document.createElement('button');b.textContent=name;b.classList.toggle('active',frame===galleryAction);b.onclick=()=>{galleryAction=frame;document.querySelectorAll('nav button').forEach(btn=>btn.classList.toggle('active',btn===b));};document.getElementById('actions').append(b);}
for(const [file,names] of Object.entries(galleryGroups)){const img=new Image(),meta=animationSheetMetadata[file],link=document.createElement('a');link.href='assets/animation/'+file;link.download=file;link.textContent=file;document.getElementById('files').append(link);img.onload=()=>{const sheet=document.createElement('canvas');sheet.width=384;sheet.height=names.length*64;const c=sheet.getContext('2d');for(let row=0;row<names.length;row++){const boxes=meta.boxes.slice(row*6,row*6+6),scale=54/Math.max(...boxes.map(b=>Math.max(b[2]-b[0],b[3]-b[1])));for(let f=0;f<6;f++){const [x,y,right,bottom]=boxes[f],w=right-x,h=bottom-y;c.drawImage(img,x,y,w,h,f*64+(64-w*scale)/2,row*64+58-h*scale,w*scale,h*scale);}}for(let row=0;row<names.length;row++){const article=document.createElement('article'),title=document.createElement('h2'),preview=document.createElement('canvas'),frames=document.createElement('canvas');title.textContent=names[row];preview.width=256;preview.height=132;preview.className='preview';preview.setAttribute('aria-label','Animation '+names[row]);frames.width=384;frames.height=64;frames.className='frames';frames.getContext('2d').drawImage(sheet,0,row*64,384,64,0,0,384,64);article.append(title,preview,frames);document.getElementById('gallery').append(article);galleryCards.push({sheet,row,canvas:preview,file,strip:frames,showWalk:false});}galleryLoaded++;document.getElementById('status').textContent=galleryLoaded===5?'Đã tải sheet trạng thái · Chu kỳ đi 8 khung đang tải.':'Đã tải '+galleryLoaded+'/5 sheet';};img.onerror=()=>document.getElementById('status').textContent='Không tải được '+file;img.src=link.href;}
// MODIFIED v12.2: eight-frame loop, stable anchors and one opaque image at a time.
for(const [rate,label] of [[.5,'Chậm ½×'],[1,'Bình thường'],[1.5,'Nhanh 1½×']]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>gallerySpeed=rate;document.getElementById('actions').append(b);}
function galleryAnimate(time){const dt=lastGalleryTime===null?0:Math.min(.05,Math.max(0,(time-lastGalleryTime)/1000));lastGalleryTime=time;galleryClock+=dt*gallerySpeed;let cyclesReady=0;for(const a of walkCycleAssets.values())if(a.ready)cyclesReady++;if(galleryLoaded===5&&cyclesReady===5)document.getElementById('status').textContent='Đã tải đủ 10 sheet · 238 khung · Chu kỳ đi 8 khung';for(const card of galleryCards){const c=card.canvas.getContext('2d'),cycle=walkCycleAssets.get(walkingSheetFile(card.file)),walk=galleryAction===1&&cycle?.ready,frame=walk?Math.floor(galleryClock*10)%8:galleryAction===1?(Math.floor(time/180)%2?2:1):galleryAction,source=walk?cycle.sheet:card.sheet;c.clearRect(0,0,256,132);c.imageSmoothingEnabled=true;c.drawImage(source,frame*64,card.row*64,64,64,68,4,120,120);const strip=card.strip.getContext('2d');if(card.showWalk!==walk){card.showWalk=walk;card.strip.width=walk?512:384;strip.clearRect(0,0,card.strip.width,64);strip.drawImage(source,0,card.row*64,card.strip.width,64,0,0,card.strip.width,64);}}requestAnimationFrame(galleryAnimate);}requestAnimationFrame(galleryAnimate);
for(const file of Object.keys(walkSheetMetadata)){const link=document.createElement('a');link.href='assets/animation/'+file;link.download=file;link.textContent=file;document.getElementById('files').append(link);}
